function renderVenture() {
  const g=engine.g,roundUI=s=>{const p=engine.getStartupFundingRoundPlan(s.id);if(!p)return'';const side=(x,label,action,kind)=>x.ownershipBefore>0?`<section class="item"><div><strong>${label}持分 ${pct(x.ownershipBefore)}</strong><p>追加出資しなければ ${pct(x.ownershipWithoutParticipation)}へ希薄化します</p><p>持分維持に必要 ${compactYen(x.proRataRequired)} · 出資済 ${compactYen(x.contributed)} · 残り ${compactYen(x.remaining)}</p></div>${btn(`${label}で追加出資`,action,{kind:`${kind} small`,data:`data-id="${s.id}"`,disabled:x.remaining<=0})}</section>`:'';return`<div class="notice" data-startup-funding-round><h3>${esc(p.round)} 追加資金調達</h3><div class="kpi-grid mini">${stat('Pre-money',compactYen(p.preMoneyValuation))}${stat('調達額',compactYen(p.targetRaise))}${stat('Post-money',compactYen(p.postMoneyValuation))}${stat('締切',`あと${p.weeksRemaining}週`)}</div>${side(p.company,'会社','follow-on-startup-company','primary')}${side(p.personal,'個人','follow-on-startup-personal','secondary')}</div>`;};return `${card('ベンチャー投資',`<div class="kpi-grid">${stat('投資先',`${g.startups.filter(s=>s.ownedCompany+s.ownedPersonal>0).length}社`)}${stat('連結子会社',`${g.subsidiaries.length}社`)}${stat('会社VC評価',compactYen(g.startups.reduce((a,s)=>a+s.valuation*s.ownedCompany,0)))}${stat('個人VC評価',compactYen(g.startups.reduce((a,s)=>a+s.valuation*s.ownedPersonal,0)))}</div>`,{subtitle:'Seed〜Pre-IPO、追加ラウンド、希薄化、IPO転換、子会社化'})}
  <div class="grid two">${g.startups.map(s=>{const active=!!engine.getStartupFundingRoundPlan(s.id);const dd=s.dueDiligence?.done?`<p class="muted">DD結果：${badge(s.dueDiligence.verdict,s.dueDiligence.verdict==='優良'?'good':s.dueDiligence.verdict==='危険'?'warn':'')}${s.dueDiligence.discount>0?` 交渉による評価額${pct(s.dueDiligence.discount)}割引`:''}${s.dueDiligence.flags.length?` · ${s.dueDiligence.flags.map(esc).join('、')}`:''}</p>`:`<div class="button-row">${btn('詳細DDを実施','conduct-startup-dd',{kind:'ghost small',data:`data-id="${s.id}"`,disabled:!s.alive})}</div>`;return card(s.name,`<div class="item-metrics"><span>${badge(s.stage,s.alive?'':'warn')}</span><span>${s.alive?'運営中':'終了'}</span></div><p>${s.domain} · 評価額 ${compactYen(s.valuation)} · 成長率 ${pct(s.growth)} · リスク ${pct(s.risk)}</p><div class="kpi-grid mini">${stat('会社持分',pct(s.ownedCompany))}${stat('個人持分',pct(s.ownedPersonal))}${stat('Runway',`${s.runwayWeeks}週`)}${stat('開発進捗',pct(s.productProgress))}</div>${roundUI(s)}${dd}<div class="button-row">${btn('会社で投資','invest-startup-company',{kind:'primary small',data:`data-id="${s.id}"`,disabled:!s.alive||active})}${btn('個人で投資','invest-startup-personal',{kind:'secondary small',data:`data-id="${s.id}"`,disabled:!s.alive||active})}${btn('子会社化','make-subsidiary',{kind:'ghost small',data:`data-id="${s.id}"`,disabled:s.ownedCompany<.5||s.subsidiary||active})}${btn('会社持分をセカンダリー売却','sell-startup-secondary-confirm',{kind:'ghost small',data:`data-id="${s.id}" data-kind="company"`,disabled:!s.alive||active||s.subsidiary||s.ownedCompany<=0})}${btn('個人持分をセカンダリー売却','sell-startup-secondary-confirm',{kind:'ghost small',data:`data-id="${s.id}" data-kind="personal"`,disabled:!s.alive||active||s.subsidiary||s.ownedPersonal<=0})}</div>`)}).join('')}</div>
  ${card('VC由来子会社',g.subsidiaries.length?g.subsidiaries.map(s=>`<article class="item"><div><h3>${s.name} ${badge(s.status,s.status==='active'?'good':'warn')}</h3><p>${s.domain} · 持分${pct(s.ownership)} · 評価額${compactYen(s.valuation)} · 週次利益${compactYen(s.weeklyProfit)}</p></div>${s.publicCompany?badge(`${s.ticker} 上場済み`,'good'):btn('子会社IPO','ipo-subsidiary',{kind:'primary small',data:`data-id="${s.id}"`})}</article>`).join(''):empty('持分50%以上で子会社化できます。'))}${renderVentureExpansion()}`;
}

function pmiBadge(s){const map={planning:['PMI計画待ち','warn'],integrating:['PMI進行中','good'],stalled:['PMI停滞','danger'],completed:['統合完了','good']};const v=map[s.pmiStatus]||['PMI未設定','warn'];return badge(v[0],v[1]);}
