// The weekly modal showed 売上/費用/利益 next to 会社現金 with nothing connecting them, so a
// profitable week that still burned cash (buying inventory, paying a deposit, servicing debt)
// read as a contradiction. The 決算 tab already has a full cash flow statement, but that is not
// the screen a player sees every single week. This reconstructs the same figures as a short
// profit-to-cash bridge from finance.js's existing statement -- no new modelling, and every
// step is an exact identity finance.js already validates:
//   netIncome + depreciation + workingCapital = operatingCF
//   opening + operatingCF + investingCF + financingCF = ending
// Any residual (from a category this bridge does not name individually) is surfaced as その他
// rather than silently swallowed, so the column always ties to the cash actually held.
function weeklyCashBridge(){
  const b=financeModule.cashBridge(engine.g,'week');
  const rows=[['当期利益',b.netIncome],['減価償却など非現金費用',b.depreciation],['運転資本の増減（在庫・売掛・買掛）',b.workingCapital]];
  if(Math.round(b.other)!==0)rows.push(['その他',b.other]);
  rows.push(['営業キャッシュフロー',b.operating,'subtotal'],['投資（設備・保証金など）',b.investing],['財務（借入・返済・配当）',b.financing],['今週の現金増減',b.netCashChange,'subtotal']);
  const line=([label,value,tone])=>`<li class="${tone==='subtotal'?'up':value<0?'down':''}"><span>${esc(label)}</span><strong>${value<0?'-':''}${compactYen(Math.abs(value))}</strong></li>`;
  return `<section class="weekly-impact-section" aria-labelledby="weekly-cash-bridge-title"><h3 id="weekly-cash-bridge-title">利益と現金の差</h3><p class="hint">黒字でも現金が減ることがあります。利益から今週の現金増減までの内訳です。</p><ul class="weekly-impact-list">${rows.map(line).join('')}</ul><p class="hint">期首現金 ${compactYen(b.openingCash)} → 期末現金 ${compactYen(b.endingCash)}</p></section>`;
}
function showWeeklySummary(summary){if(!summary)return;const impact=dashboardModule.weeklyImpact(engine.g,{companyValue:engine.companyValue()});const moneyDelta=v=>dashboardModule.deltaLabel(v,compactYen);const rows=impact.metrics.map(m=>`<article class="weekly-impact-card ${m.tone}"><span>${esc(m.label)}</span><strong>${compactYen(m.value)}</strong><small>${m.hasDelta?moneyDelta(m.delta):'前週比較なし'}</small></article>`).join('');const highlights=impact.highlights.length?impact.highlights.map(h=>`<li class="${h.tone}"><span>${esc(h.label)}</span><strong>${moneyDelta(h.delta)}</strong></li>`).join(''):'<li><span>比較対象</span><strong>比較できる前週データがありません</strong></li>';modal(`<div class="summary-head"><span>第${summary.week}週</span><h2>週間経営レポート</h2><p>前週から何が変わったかを確認し、次の一手へつなげます。</p></div><div class="weekly-impact-grid" aria-label="週送り後の変化">${rows}</div><section class="weekly-impact-section" aria-labelledby="weekly-impact-title"><h3 id="weekly-impact-title">今週の変化</h3><ul class="weekly-impact-list">${highlights}</ul></section><div class="kpi-grid">${stat('売上',compactYen(summary.sales))}${stat('費用',compactYen(summary.expenses))}${stat('利益',compactYen(summary.profit))}${stat('会社現金',compactYen(summary.companyCash))}${stat('企業価値',compactYen(summary.companyValue))}${stat('個人資産',compactYen(summary.personalNetWorth))}</div>${weeklyCashBridge()}<h3>主なニュース</h3>${summary.newNews.map(n=>`<div class="news-line">${esc(n)}</div>`).join('')||empty('新しいニュースはありません。')}<div class="modal-actions">${btn('閉じる','close-modal',{kind:'primary'})}${btn('次の優先タスクを見る','tab',{kind:'secondary',data:'data-tab="home"'})}</div>`,'summary-modal');}

function askMoney(title,defaultValue,callback){modal(`<h2>${esc(title)}</h2>${moneyInput('modal-money',defaultValue,'金額（円）')}<div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn primary" id="modal-ok">実行</button></div>`);$('#modal-ok').onclick=()=>{const v=Number($('#modal-money').value.replace(/,/g,''));closeModal();callback(v);};setTimeout(()=>$('#modal-money')?.select(),0);}
function askText(title,label,defaultValue,callback){modal(`<h2>${esc(title)}</h2><label class="field"><span>${esc(label)}</span><input id="modal-text" value="${esc(defaultValue)}"></label><div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn primary" id="modal-ok">実行</button></div>`);$('#modal-ok').onclick=()=>{const v=$('#modal-text').value;closeModal();callback(v);};}
// 出店の最終確認。マップ画面の試算(storeOpeningEstimate)と同じengine.estimateStoreOpening()を
// 再利用し、店舗名入力だけだった旧askTextフローに費用・期待利益・出店後現金を再表示する。
function confirmOpenStore(tenantID,businessID){
  const defaultName=`${engine.g.companyName} ${engine.g.stores.length+1}号店`;
  const e=engine.estimateStoreOpening({tenantID,businessID,operatingHours:3});
  if(!e){askText('新店舗','店舗名',defaultName,name=>engine.openStore({tenantID,businessID,name,operatingHours:3}));return;}
  const tone=!e.affordable?'danger':e.profitable?'good':'warn';
  const verdict=!e.affordable?`資金不足（あと${compactYen(e.upfront-e.companyCash)}）`:e.profitable?`回収まで約${e.paybackWeeks}週`:'この条件では赤字見込み';
  const band=`${compactYen(e.conservative.profit)} 〜 ${compactYen(e.optimistic.profit)}`;
  modal(`<h2>出店の最終確認</h2><p>${esc(e.prefName)}・${esc(e.tenantName)}に${esc(e.businessName)}を出店します。</p><p>${badge(verdict,tone)}</p><div class="kpi-grid mini">${stat('週次利益（期待）',compactYen(e.expected.profit),`幅 ${band}`)}${stat('初期費用',compactYen(e.upfront),`設備${compactYen(e.storeCost)} + 保証金${compactYen(e.deposit)}`)}${stat('出店後の会社現金',compactYen(e.cashAfterOpening))}${stat('開店まで',`${e.weeksToOpen}週`)}</div><label class="field"><span>店舗名</span><input id="modal-text" value="${esc(defaultName)}"></label><div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn primary" id="modal-ok">この内容で出店する</button></div>`);
  $('#modal-ok').onclick=()=>{const name=$('#modal-text').value;closeModal();engine.openStore({tenantID,businessID,name,operatingHours:3});};
}
// 閉店の最終確認。confirmOpenStore()と対になる「やめる」側の導線で、実行前に結果を明示する。
// engine.storeClosurePlan() が計算し、ここは表示だけを行う。
function confirmCloseStore(storeID){
  const c=engine.storeClosurePlan?.(storeID);
  if(!c)return;
  const losing=c.weeklyProfit<0;
  const verdict=losing?`この店舗は週次${compactYen(c.weeklyProfit)}の赤字です`:`この店舗は週次${compactYen(c.weeklyProfit)}の黒字です`;
  modal(`<h2>閉店の最終確認</h2><p>${esc(c.prefName)}の${esc(c.storeName)}（${esc(c.businessName)}）を閉店します。</p><p>${badge(verdict,losing?'warn':'danger')}</p><div class="kpi-grid mini">${stat('設備の売却額',compactYen(c.proceeds),`取得費${compactYen(c.storeCost)}の${Math.round(c.salvageRate*100)}%`)}${stat('返還されない保証金',compactYen(c.forfeitedDeposit),'没収損として計上')}${stat('現金の増減',`+${compactYen(c.netCashChange)}`,'保証金は現金を伴いません')}${stat('失う週次売上',compactYen(c.weeklySales))}</div><p class="hint">在庫は除却され、配属スタッフは解散します。テナントは空き物件に戻り、他社が入居できるようになります。閉店した店舗は元に戻せません。</p><div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn danger" id="modal-ok">閉店する</button></div>`);
  $('#modal-ok').onclick=()=>{closeModal();engine.closeStore(storeID);};
}
// 個人不動産の開発・再開発の中止確認。start側は全額前払いのため、中止しても返金は無い
// （engine.getPersonalRealEstateRedevelopmentCancelPlan() が計算し、ここは表示だけを行う）。
function confirmCancelPersonalRedevelopment(assetID){
  const c=engine.getPersonalRealEstateRedevelopmentCancelPlan?.(assetID);
  if(!c)return;
  modal(`<h2>開発・再開発の中止確認</h2><p>${esc(c.name)}の${esc(c.projectLabel)}（完了まであと${c.weeksLeft}週）を中止します。</p><p>${badge('支払済みの費用は返金されません','danger')}</p><div class="kpi-grid mini">${stat('失う支払済み費用',compactYen(c.forfeitedCost))}${stat('失う完了時の評価額増加',compactYen(c.forfeitedValueGain))}</div><p class="hint">中止すると別の開発・再開発をすぐに開始できます。中止した進捗は元に戻せません。</p><div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn danger" id="modal-ok">中止する</button></div>`);
  $('#modal-ok').onclick=()=>{closeModal();engine.cancelPersonalRealEstateRedevelopment(assetID);};
}
// 部門閉鎖の最終確認。退職金は engine.departmentClosurePlan() の試算をそのまま表示する
// （closeDepartment() 側も同じ workforce.departmentSeverance() を参照するため一致する）。
function confirmCloseDepartment(id){
  const c=engine.departmentClosurePlan?.(id);
  if(!c)return;
  const campaignNote=c.activeCampaignCount>0?`<p class="hint">進行中のキャンペーン${c.activeCampaignCount}件は中止され、使用済み予算は戻りません。</p>`:'';
  modal(`<h2>部門閉鎖の最終確認</h2><p>${esc(c.name)}を閉鎖します。</p>${c.severance>0?badge('退職金の支払いが発生します','danger'):''}<div class="kpi-grid mini">${stat('在籍人員',`${c.headcount}名`)}${stat('退職金',compactYen(c.severance))}${stat('週次費の削減',compactYen(c.weeklyCost))}</div>${campaignNote}<p class="hint">閉鎖するとこの部門が解放していた機能は再び利用できなくなります。再設置には設置費が再度かかります。</p><div class="modal-actions">${btn('キャンセル','close-modal',{kind:'ghost'})}<button class="btn danger" id="modal-ok">閉鎖する</button></div>`);
  $('#modal-ok').onclick=()=>{closeModal();engine.closeDepartment(id);};
}

